SELECT MIN(s.seller_id), s.name, COUNT(DISTINCT o.order_id) AS orders FROM order_items oi JOIN orders o ON o.order_id = oi.order_id JOIN sellers s ON s.seller_id = oi.seller_id WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2026-04-01' AND DATE '2026-06-30' AND s.name = 'Jamuna Fashion' GROUP BY s.name
